 "content": "def transform(grid):
    """Tile the grid in the four quarter-turn orientations."""
    original = [row[:] for row in grid]
    clockwise = [list(row) for row in zip(*original[::-1])]
    counterclockwise = [list(row) for row in zip(*original)][::-1]
    half_turn = [row[::-1] for row in original[::-1]]

    return [
        top_left + top_right
        for top_left, top_right in zip(original, clockwise)
    ] + [
        bottom_left + bottom_right
        for bottom_left, bottom_right in zip(counterclockwise, half_turn)
    ]
